<template><div class="p-2"><el-alert title="项目管理授权仅限平台超级管理员维护；管理范围不等同业务数据访问范围。" type="warning" :closable="false" /><el-button class="mt-2" v-hasPermi="['property:projectAdminScope:add']" type="primary" @click="openAdd">新增授权</el-button><el-table :data="rows" v-loading="loading" class="mt-2"><el-table-column label="主体类型"><template #default="{row}"><dict-tag :options="pm_management_principal_type" :value="row.principalType" /></template></el-table-column><el-table-column prop="principalId" label="主体 ID" /><el-table-column label="范围"><template #default="{row}"><dict-tag :options="pm_management_scope_type" :value="row.scopeType" /></template></el-table-column><el-table-column prop="projectId" label="项目 ID" /><el-table-column label="状态"><template #default="{row}"><dict-tag :options="sys_normal_disable" :value="row.status" /></template></el-table-column><el-table-column label="操作"><template #default="{row}"><el-button link v-hasPermi="['property:projectAdminScope:edit']" @click="toggle(toGrant(row))">{{row.status==='0'?'停用':'启用'}}</el-button><el-button link type="danger" v-hasPermi="['property:projectAdminScope:remove']" @click="revoke(toGrant(row))">撤销</el-button></template></el-table-column></el-table><el-dialog v-model="visible" title="新增项目管理授权"><el-form :model="form"><el-form-item label="主体类型"><el-radio-group v-model="form.principalType"><el-radio v-for="dict in pm_management_principal_type" :key="dict.value" :value="dict.value">{{dict.label}}</el-radio></el-radio-group></el-form-item><el-form-item label="主体 ID"><el-input v-model="form.principalId"/></el-form-item><el-form-item label="范围"><el-radio-group v-model="form.scopeType"><el-radio v-for="dict in pm_management_scope_type" :key="dict.value" :value="dict.value">{{dict.label}}</el-radio></el-radio-group></el-form-item><el-form-item v-if="form.scopeType==='PROJECT'" label="项目 ID"><el-input v-model="form.projectId"/></el-form-item></el-form><template #footer><el-button @click="visible=false">取消</el-button><el-button type="primary" @click="submit">确定</el-button></template></el-dialog></div></template>
<script setup lang="ts">import {onMounted,ref} from 'vue'; import {addProjectManagementGrant,changeProjectManagementGrantStatus,listProjectManagementGrants,revokeProjectManagementGrant} from '@/api/property/project/admin-scope'; import type {ProjectManagementGrantForm,ProjectManagementGrantVO} from '@/api/property/project/admin-scope/types'; import {useDict} from '@/utils/dict'; const dicts=useDict('pm_management_principal_type','pm_management_scope_type','sys_normal_disable'),pm_management_principal_type=computed(()=>dicts.pm_management_principal_type||[]),pm_management_scope_type=computed(()=>dicts.pm_management_scope_type||[]),sys_normal_disable=computed(()=>dicts.sys_normal_disable||[]); const rows=ref<ProjectManagementGrantVO[]>([]),loading=ref(false),visible=ref(false),form=ref<ProjectManagementGrantForm>({principalType:'USER',principalId:'',scopeType:'ALL'}); const toGrant=(row: Record<string, unknown>): ProjectManagementGrantVO=>{const id=row.id,principalId=row.principalId,projectId=row.projectId,version=row.version,principalType=row.principalType,scopeType=row.scopeType,status=row.status;if((typeof id!=='string'&&typeof id!=='number')||(typeof principalId!=='string'&&typeof principalId!=='number')||(typeof projectId!=='string'&&typeof projectId!=='number')||typeof version!=='number'||(principalType!=='USER'&&principalType!=='ROLE')||(scopeType!=='ALL'&&scopeType!=='PROJECT')||typeof status!=='string')throw new Error('授权列表返回了无效记录');return {id,principalType,principalId,scopeType,projectId,status,version};}; const load=async()=>{loading.value=true;try{const response=await listProjectManagementGrants({pageNum:1,pageSize:100});rows.value=response.data.rows;}finally{loading.value=false;}}; const openAdd=()=>{form.value={principalType:'USER',principalId:'',scopeType:'ALL'};visible.value=true;}; const submit=async()=>{await addProjectManagementGrant(form.value);visible.value=false;await load();}; const toggle=async(row:ProjectManagementGrantVO)=>{await changeProjectManagementGrantStatus(row.id,{status:row.status==='0'?'1':'0',version:row.version});await load();}; const revoke=async(row:ProjectManagementGrantVO)=>{await revokeProjectManagementGrant(row.id,row.version);await load();};onMounted(load);</script>
